/** 预设 id → 品牌 logo；未收录（含 custom）返回 undefined，由调用方退到中性图标。 */
const PRESET_LOGOS: Record<string, ComponentType<LogoProps>> = {
  zhipu: ZhipuLogo,
  minimax: MinimaxLogo,
  "minimax-cn": MinimaxLogo,
  moonshot: KimiLogo,
  "moonshot-cn": KimiLogo,
  dashscope: QwenLogo,
  "dashscope-cn": QwenLogo,
  volcengine: VolcengineLogo,
  stepfun: StepFunLogo,
  "stepfun-cn": StepFunLogo,
  tencent: TencentCloudLogo,
  baidu: BaiduCloudLogo,
  xiaomi: XiaomiMimoLogo,
  longcat: LongCatLogo,
  sensenova: SenseNovaLogo,
  xunfei: SparkLogo,
  modelscope: ModelScopeLogo,
  siliconflow: SiliconCloudLogo,
  "siliconflow-cn": SiliconCloudLogo,
  groq: GroqLogo,
  openrouter: OpenRouterLogo,
  "new-api": NewApiLogo,
  ollama: OllamaLogo,
  lmstudio: LmStudioLogo,
};

export function providerPresetLogo(
  presetId: string | undefined,
): ComponentType<LogoProps> | undefined {
  return presetId ? PRESET_LOGOS[presetId] : undefined;
}
